require __DIR__.'/lib.php';public_origin();rate('lead',8,3600);$d=body();if(($d['consent']??false)!==true)out(400,['erro'=>'Autorize o envio do pedido para continuar.']);$name=txt($d['name']??'',120);$phone=preg_replace('/\D/','',txt($d['phone']??'',30));if($name===''||!preg_match('/^\d{10,15}$/',$phone))out(400,['erro'=>'Informe seu nome e um telefone com DDD.']);$brief=$d['brief']??[];if(!is_array($brief))out(400,['erro'=>'Pedido inválido.']);$safe=[];foreach(['business','city','description','amenities','rooms','whatsapp','template','product','plan','domain']as$k)$safe[$k]=txt($brief[$k]??'',in_array($k,['description','rooms','amenities'])?2000:300);$safe['customSite']=($brief['customSite']??false)===true;$settings=settings();$product=$safe['product'];if($product==='pms')$safe['customSite']=false;if(!in_array($product,['site','pms','combo'],true))out(400,['erro'=>'Escolha um produto válido.']);$model=null;foreach($settings['models'] as $m)if($m['id']===$safe['template']&&$m['enabled'])$model=$m;if($safe['template']!==''&&!$model)out(400,['erro'=>'Este modelo não está disponível. Escolha outro na galeria.']);$plan=null;foreach($settings['plans'] as $p)if($p['id']===($product==='combo'?'com-bia':$safe['plan'])&&$p['enabled'])$plan=$p;if($product!=='site'&&!$plan)out(400,['erro'=>'Selecione um plano disponível.']);$quote=['revision'=>$settings['revision'],'siteCash'=>$product!=='pms'&&!$safe['customSite']?($model['price']??$settings['pricing']['siteCash']):null,'customQuote'=>$safe['customSite'],'monthly'=>$product!=='site'?$plan['price']:null,'model'=>$model['name']??'A definir','plan'=>$plan['name']??null];$id=bin2hex(random_bytes(12));$dir=private_dir().'/leads';if(!is_dir($dir))mkdir($dir,0700,true);$lead=['id'=>$id,'name'=>$name,'phone'=>$phone,'email'=>txt($d['email']??'',200),'brief'=>$safe,'quote'=>$quote,'status'=>'novo','notes'=>'','consent'=>true,'created'=>gmdate('c')];atomic_json($dir.'/'.$id.'.json',$lead);out(201,['id'=>$id,'message'=>'Pedido de proposta registrado. Nenhum pagamento ou reserva foi realizado.']);
